        &&& g.0.instance_id() == unbounded_log_instance@.id()
        &&& g.0.key() == i
        &&& g.0.value() == v
        &&& g.1.instance_id() == cyclic_buffer_instance@.id()
        &&& g.1.key() == i
        &&& g.1.value() == v
        &&& 0 <= v <= MAX_IDX
    }
}
}  


